class Solution:
    def maximumBags(self, capacity: list[int], rocks: list[int], additionalRocks: int) -> int:
        gaps = sorted(cap - rock for cap, rock in zip(capacity, rocks))
        full = 0
        for gap in gaps:
            if gap <= additionalRocks:
                additionalRocks -= gap
                full += 1
            else:
                break
        return full

